<template><section class="panel" data-testid="sequence-coordinate-atlas"><h3>Complete chromosome / contig coordinate atlas</h3><div class="sequence-viz-controls"><label>Track<select v-model="chart" class="input"><option value="GD15">Island proxy median / IQR</option><option value="GD02">Cumulative imported G−C counts</option></select></label><label>seqid ({{ catalog.length }} available)<select v-model="seqid" class="input"><option v-for="s in catalog" :key="s.seqid" :value="s.seqid">{{ s.seqid }} · {{ s.n }} records</option></select></label><label>Start bp<input v-model.number="start" type="number" class="input"/></label><label>End bp<input v-model.number="end" type="number" class="input"/></label><button class="btn" @click="page=1;loadWindow()">Open exact window</button></div><p v-if="error">{{ error }}</p><SequenceFigure v-if="track" :figure="figure" :chart-id="chart" :species-id="speciesId" omics="genome" :scope="scope"/><p class="sequence-viz-caption">The overview covers all {{ track?.n }} placed records in this seqid. Excluded cumulative increments: {{ track?.excluded_increment_n }}. {{ total }} records in the selected exact window.</p><div class="sequence-viz-controls"><button class="btn subtle" :disabled="page<=1" @click="page--;loadWindow()">Previous records</button><span>Page {{ page }}</span><button class="btn subtle" :disabled="page*100>=total" @click="page++;loadWindow()">Next records</button><a :href="download">All coordinates / scores CSV</a></div><div class="table-wrap"><table><thead><tr><th>Native gene ID</th><th>Start</th><th>End</th><th>Value</th></tr></thead><tbody><tr v-for="r in rows" :key="r.gene_id"><td><button class="sequence-viz-entity" @click="open(r)">{{ r.gene_id }}</button></td><td>{{ r.start }}</td><td>{{ r.end }}</td><td>{{ fmt(r.value) }}</td></tr></tbody></table></div></section></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';import SequenceFigure from './SequenceFigure.vue';import {sequenceGet,sequenceExport} from '../../api/sequenceVisuals';import {number as fmt} from '../../utils/sequenceFormat'
const props=defineProps({speciesId:String,scope:String,manifest:Object});const chart=ref('GD15'),catalog=ref([]),seqid=ref(''),track=ref(null),start=ref(0),end=ref(0),page=ref(1),rows=ref([]),total=ref(0),error=ref('');let seq=0,controller
const params=()=>({scope:props.scope,artifact_version:props.manifest.artifact_version,source_hash:props.manifest.source_hash,chart_id:chart.value,...(seqid.value?{seqid:seqid.value}:{})});const figure=computed(()=>({...props.manifest,chart_id:chart.value,title:seqid.value,status:track.value?.status||'available',coverage:{n_source:track.value?.n},data:{kind:chart.value==='GD02'?'chromosome_cumulative_tracks':'chromosome_score_tracks',tracks:track.value?[track.value]:[]}}));const download=computed(()=>sequenceExport(props.speciesId,'genome',{...params(),kind:'complete_rows'}))
async function load(){const current=++seq;controller?.abort();controller=new AbortController();try{const r=await sequenceGet(props.speciesId,'genome','coordinates/',params(),{signal:controller.signal});if(seq!==current)return;catalog.value=r.catalog;track.value=r.track;if(!seqid.value)seqid.value=r.track.seqid;start.value=r.track.min;end.value=r.track.max;page.value=1;await loadWindow()}catch(e){if(seq===current&&!controller.signal.aborted)error.value=e.message}}
async function loadWindow(){const current=++seq;controller?.abort();controller=new AbortController();try{const r=await sequenceGet(props.speciesId,'genome','coordinates/',{...params(),resolution:'window',start:start.value,end:end.value,page:page.value,page_size:100},{signal:controller.signal});if(seq!==current)return;rows.value=r.rows;total.value=r.total;error.value=''}catch(e){if(seq===current&&!controller.signal.aborted)error.value=e.message}}
function open(r){window.dispatchEvent(new CustomEvent('stoich-entity-chart-click',{detail:{...r,species_id:props.speciesId}}))}
watch(()=>[props.speciesId,props.scope,props.manifest.artifact_version],()=>{seqid.value='';rows.value=[];load()},{immediate:true});watch([seqid,chart],load);onBeforeUnmount(()=>{seq++;controller?.abort()})
</script>
